import path from "node:path";
import { parentPort } from "node:worker_threads";

const SAMPLE_RATE = 16000;
const WINDOW_SECONDS = 30;
const MAX_PROMPT_TOKENS = 200;
const WHISPER_MAX_TOKENS = 448;

let loaded = null;

async function load({ folder, dtype }) {
  const key = `${folder}\n${dtype}`;
  if (loaded?.key === key) return loaded;
  await loaded?.model.dispose();
  loaded = null;
  const { AutoModelForSpeechSeq2Seq, AutoProcessor, env } = await import("@huggingface/transformers");
  env.allowRemoteModels = false;
  env.allowLocalModels = true;
  env.useFSCache = false;
  env.localModelPath = `${path.dirname(folder)}${path.sep}`;
  const id = path.basename(folder);
  const [processor, model] = await Promise.all([
    AutoProcessor.from_pretrained(id, { local_files_only: true }),
    AutoModelForSpeechSeq2Seq.from_pretrained(id, { local_files_only: true, dtype, device: "cpu" }),
  ]);
  loaded = { key, processor, model, tokenizer: processor.tokenizer };
  return loaded;
}

const lastToken = REDACTED => Number(output.tolist()[0].at(-1));

async function whisper({ processor, model, tokenizer }, samples, prompt) {
  const config = model.generation_config;
  const { input_features } = await processor(samples);
  const promptIds = prompt && config.prev_sot_token_id ? tokenizer.encode(` ${prompt}`, { add_special_tokens: false }).slice(-MAX_PROMPT_TOKENS) : [];
  const start = [...(promptIds.length ? [config.prev_sot_token_id, ...promptIds] : []), config.decoder_start_token_id];
  if (config.is_multilingual) {
    const language = lastToken(await model.generate({ inputs: input_features, decoder_input_ids: start, max_new_tokens: 1 }));
    const languages = new Set(Object.values(config.lang_to_id));
    start.push(languages.has(language) ? language : config.lang_to_id["<|en|>"], config.task_to_id.transcribe);
  }
  start.push(config.no_timestamps_token_id);
  const output = await model.generate({ inputs: input_features, decoder_input_ids: start, max_new_tokens: WHISPER_MAX_TOKENS - start.length - 1 });
  return tokenizer.decode(output.tolist()[0].slice(start.length), { skip_special_tokens: true });
}

async function moonshine({ processor, model, tokenizer }, samples) {
  const inputs = await processor(samples);
  const output = await model.generate({ ...inputs, max_new_tokens: Math.ceil(samples.length / SAMPLE_RATE) * 6 + 8 });
  return tokenizer.batch_decode(output, { skip_special_tokens: true })[0];
}

async function transcribe({ folder, family, dtype, samples, prompt }) {
  const runtime = await load({ folder, dtype });
  const window = SAMPLE_RATE * WINDOW_SECONDS;
  const texts = [];
  for (let offset = 0; offset < samples.length; offset += window) {
    const chunk = samples.subarray(offset, offset + window);
    texts.push(family === "whisper" ? await whisper(runtime, chunk, prompt) : await moonshine(runtime, chunk));
  }
  return texts.map(text => text.trim()).filter(Boolean).join(" ");
}

parentPort?.on("message", async ({ id, job }) => {
  try { parentPort?.postMessage({ id, text: await transcribe(job) }); }
  catch (cause) { parentPort?.postMessage({ id, error: cause instanceof Error ? cause.message : String(cause) }); }
});
import { SPEECH_ENGINES, type SpeechEngineId } from "@/lib/settings";
import { VOICE_NEEDS_OPENAI_KEY } from "@/lib/ai/voice-access";
import { SPEECH_ENGINE_LABELS, type BatchSpeechEngines, type SpeechAudio, type SpeechHints } from "./engine";

export type SpeechAvailability = Record<SpeechEngineId, boolean>;
export type SpeechChoice = { engine: SpeechEngineId; fellBack: boolean } | { engine: null; reason: string };
export type SpeechResult =
  | { ok: true; text: string; engine: SpeechEngineId; fellBack: boolean }
  | { ok: false; reason: string; status: 502 | 503 };

const withoutFallback = (chosen: SpeechEngineId) => chosen === "openai" ? VOICE_NEEDS_OPENAI_KEY
  : `${SPEECH_ENGINE_LABELS[chosen]} is not available, and there is no OpenAI API key to fall back to. Add an OpenAI key in Settings or choose another speech-to-text engine.`;

export function chooseSpeechEngine(chosen: SpeechEngineId, available: SpeechAvailability): SpeechChoice {
  if (available[chosen]) return { engine: chosen, fellBack: false };
  return available.openai ? { engine: "openai", fellBack: true } : { engine: null, reason: withoutFallback(chosen) };
}

export async function speechAvailability(engines: BatchSpeechEngines): Promise<SpeechAvailability> {
  const entries = await Promise.all(SPEECH_ENGINES.map(async id => [id, await (engines[id]?.available().catch(() => false) ?? false)] as const));
  return Object.fromEntries(entries) as SpeechAvailability;
}

export async function transcribeWithFallback({ chosen, engines, audio, hints, signal }: {
  chosen: SpeechEngineId; engines: BatchSpeechEngines; audio: SpeechAudio; hints: SpeechHints; signal?: AbortSignal;
}): Promise<SpeechResult> {
  const available = await speechAvailability(engines);
  const choice = chooseSpeechEngine(chosen, available);
  if (!choice.engine) return { ok: false, reason: choice.reason, status: 503 };
  const attempt = (engine: SpeechEngineId) => engines[engine]!.transcribe(audio, hints, signal).then(text => text.trim(), () => {
    console.warn("[speech] engine-failed", engine);
    return null;
  });
  const failed: SpeechResult = { ok: false, reason: "Voice input is unavailable. Try again.", status: 502 };
  const first = await attempt(choice.engine);
  if (first !== null) return { ok: true, text: first, engine: choice.engine, fellBack: choice.fellBack };
  if (choice.engine === "openai" || !available.openai) return failed;
  const second = await attempt("openai");
  return second === null ? failed : { ok: true, text: second, engine: "openai", fellBack: true };
}
import { z } from "zod";
import type { SpeechAudio } from "./engine";

export const MAX_SPEECH_BYTES = 12 * 1024 * 1024;
const WAV_HEADER_BYTES = 44;
const RATE = z.coerce.number().int().min(8000).max(48000);
const uploadSchema = z.object({ type: z.enum(["audio/pcm", "audio/wav"]), rate: RATE.optional() });

export function encodeWav({ samples, sampleRate }: SpeechAudio) {
  const dataBytes = samples.length * 2;
  const wav = new DataView(new ArrayBuffer(WAV_HEADER_BYTES + dataBytes));
  const text = (offset: number, value: string) => { for (let index = 0; index < value.length; index++) wav.setUint8(offset + index, value.charCodeAt(index)); };
  text(0, "RIFF"); wav.setUint32(4, 36 + dataBytes, true); text(8, "WAVE"); text(12, "fmt ");
  wav.setUint32(16, 16, true); wav.setUint16(20, 1, true); wav.setUint16(22, 1, true); wav.setUint32(24, sampleRate, true);
  wav.setUint32(28, sampleRate * 2, true); wav.setUint16(32, 2, true); wav.setUint16(34, 16, true); text(36, "data"); wav.setUint32(40, dataBytes, true);
  samples.forEach((sample, index) => wav.setInt16(WAV_HEADER_BYTES + index * 2, sample, true));
  return new Uint8Array(wav.buffer);
}

function pcmSamples(bytes: Uint8Array) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength - (bytes.byteLength % 2));
  return Int16Array.from({ length: view.byteLength / 2 }, (_, index) => view.getInt16(index * 2, true));
}

function parseWav(bytes: Uint8Array): SpeechAudio | null {
  if (bytes.byteLength < WAV_HEADER_BYTES) return null;
  const wav = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const tag = (offset: number) => String.fromCharCode(...bytes.subarray(offset, offset + 4));
  if (tag(0) !== "RIFF" || tag(8) !== "WAVE") return null;
  let format: { sampleRate: number } | null = null;
  for (let offset = 12; offset + 8 <= bytes.byteLength;) {
    const size = wav.getUint32(offset + 4, true), body = offset + 8;
    if (tag(offset) === "fmt " && size >= 16) {
      const supported = wav.getUint16(body, true) === 1 && wav.getUint16(body + 2, true) === 1 && wav.getUint16(body + 14, true) === 16;
      format = supported ? { sampleRate: wav.getUint32(body + 4, true) } : null;
    } else if (tag(offset) === "data") {
      const rate = RATE.safeParse(format?.sampleRate);
      return rate.success ? { samples: pcmSamples(bytes.subarray(body, Math.min(body + size, bytes.byteLength))), sampleRate: rate.data } : null;
    }
    offset = body + size + (size % 2);
  }
  return null;
}

export function decodeSpeechAudio(contentType: string | null, rate: string | null, bytes: Uint8Array): SpeechAudio | null {
  const upload = uploadSchema.safeParse({ type: contentType?.split(";")[0].trim().toLowerCase(), rate: rate ?? undefined });
  if (!upload.success || bytes.byteLength === 0 || bytes.byteLength > MAX_SPEECH_BYTES) return null;
  if (upload.data.type === "audio/wav") return parseWav(bytes);
  const samples = pcmSamples(bytes);
  return upload.data.rate && samples.length ? { samples, sampleRate: upload.data.rate } : null;
}
import type { SupabaseClient } from "@supabase/supabase-js";
import type { AiDataScope } from "@/lib/settings";
import { loadVoiceVocabulary } from "@/lib/ai/voice-vocabulary";
import type { SpeechHints } from "./engine";

export const SPEECH_PROMPT = "A short personal-finance voice note: spending, income, transfers, amounts with currencies, and names of accounts, shops and categories.";

export async function loadSpeechHints(supabase: SupabaseClient, workspaceId: string, scopes: readonly AiDataScope[]): Promise<SpeechHints> {
  return { prompt: SPEECH_PROMPT, keywords: await loadVoiceVocabulary(supabase, workspaceId, scopes).catch(() => []) };
}

const MAX_HINT_CHARACTERS = 800;
export function promptWithNames(hints: SpeechHints) {
  const names = hints.keywords.join(", ").slice(0, MAX_HINT_CHARACTERS);
  return names ? `${hints.prompt} Names that may come up: ${names}.` : hints.prompt;
}
import { z } from "zod";
import { voiceApiKey } from "@/lib/ai/configured";
import { encodeWav } from "./audio";
import { promptWithNames } from "./hints";
import type { BatchSpeechEngine } from "./engine";

const MODEL = "gpt-4o-transcribe";
const responseSchema = z.object({ text: z.string() });

export const openaiSpeech: BatchSpeechEngine = {
  available: async () => Boolean(await voiceApiKey()),
  async transcribe(audio, hints, signal) {
    const apiKey = await voiceApiKey();
    if (!apiKey) throw new Error("No OpenAI API key");
    const form = new FormData();
    form.set("model", MODEL);
    form.set("response_format", "json");
    form.set("prompt", promptWithNames(hints));
    form.set("file", new Blob([encodeWav(audio)], { type: "audio/wav" }), "voice.wav");
    const response = await fetch("https://api.openai.com/v1/audio/transcriptions", { method: "POST", headers: { Authorization: `Bearer ${apiKey}` }, body: form, signal });
    if (!response.ok) throw new Error(`OpenAI transcription failed (${response.status})`);
    return responseSchema.parse(await response.json()).text;
  },
};
